  scrpt[266] = fstr(" DIPOLE NEUTRAL DISS  F=0.002614   ELOSS= 21.117  ", 50)
  # NULL COLLISIONS
  scrptn[1] = fstr(" H2O: OH(X)  GROUND STATE DISSOCIATION             ", 50)
  scrptn[2] = fstr(" H2O: OH(A-X) 306-350 NM EMISSION                  ", 50)
  scrptn[3] = fstr(" H2O: H ALPHA 3-2 (BALMER)  656.3 NM.  EMISSION    ", 50)
  scrptn[4] = fstr(" H2O: H ALPHA 2-1 (LYMAN)   121.6 NM.  EMISSION    ", 50)
  # CALC POPULATION OF LOW ENERGY VIBRATIONAL STATE
  apopv1 = exp(ein[211] / inpt.akt)
  apopgs = 1.0
  apopsum = apopgs + apopv1
  apopv1 = apopv1 / apopsum
  # KEEP APOPGS=1 TO ALLOW FOR EXCITATIONS FROM UPPER STATE
  fdo i, 1, inpt.nstep:
    en = mix2.eg[i]
    gamma1 = (emass2 + 2.0 * en) / emass2
    gamma2 = gamma1 * gamma1
    beta = sqrt(1.0 - 1.0 / gamma2)
    beta2 = beta * beta
    block L32:
      # ELASTIC
      if en <= xel[1]:
        qela = yel[1] * 1e-16
        break L32
      block L31:
        fdo j, 2, nela:
          if en <= xel[j]: break L31
        j = nela
      y1 = ln(yel[j])
      y2 = ln(yel[j - 1])
      x1 = ln(xel[j])
      x2 = ln(xel[j - 1])
      a = (y1 - y2) / (x1 - x2)
      b = (x2 * y1 - x1 * y2) / (x2 - x1)
      qela = exp(a * ln(en) + b) * 1e-16
    block L35:
      # MOMENTUM TRANSFER ELASTIC
      if en <= xmt[1]:
        qmmt = ymt[1] * 1e-16
        break L35
      block L34:
        fdo j, 2, nmmt:
          if en <= xmt[j]: break L34
        j = nmmt
      y1 = ln(ymt[j])
      y2 = ln(ymt[j - 1])
      x1 = ln(xmt[j])
      x2 = ln(xmt[j - 1])
      a = (y1 - y2) / (x1 - x2)
      b = (x2 * y1 - x1 * y2) / (x2 - x1)
      qmmt = exp(a * ln(en) + b) * 1e-16
    block L38:
      # ANGULAR DISTRIBUTION FUNCTION OKHRIMOVSKY
      if en <= xeps[1]:
        eps = yeps[1]
        break L38
      block L37:
        fdo j, 2, neps:
          if en <= xeps[j]: break L37
        j = neps
      a = (yeps[j] - yeps[j - 1]) / (xeps[j] - xeps[j - 1])
      b = (xeps[j - 1] * yeps[j] - xeps[j] * yeps[j - 1]) / (xeps[j - 1] - xeps[j])
      eps = a * en + b
    # CONVERT TO  (1.0-EPS)
    eps = 1.0 - eps
    # USE ELASTIC
    q[2, i] = qela
    peqel[2, i] = eps
    # CAN USE ISOTROPIC ELASTIC WITH FOLLOWING COMMENTED LINES
    # Q(2,I)=QMMT
    # PEQEL(2,I)=0.0
    # IONISATION CALCULATION
    fdo j, 1, nion:
      peqion[j, i] = 0.0
      qion[j, i] = 0.0
    block L90:
      block L45:
        block L44:
          # IF ENERGY LESS THAN 5KEV CALCULATE TOTAL COUNTING AND GROSS IONISATION
          if en > 5000.0: break L44
          if en <= eion[1]: break L90
          block L43:
            fdo j, 2, nionc:
              if en <= xion[j]: break L43
            j = nionc
          a = (yionc[j] - yionc[j - 1]) / (xion[j] - xion[j - 1])
          b = (xion[j - 1] * yionc[j] - xion[j] * yionc[j - 1]) / (xion[j - 1] - xion[j])
